112:     this.inputsFiltros.forEach((input, posicion) => {
113:       if (valoresAComparar[posicion].includes(input.value.trim().toLowerCase())) {
114:         filtrosPasados++;
115:       }
116:     });
117:     return filtrosPasados === valoresAComparar.length;
118:   }
