425:   seleccionarPlan(plan: Seguimiento) {
426:     if (!plan.seleccionado) {
427:       plan.seleccionado = true;
428:       this.planesInteres = [...this.planesInteres, plan];
429:     } else if (plan.seleccionado) {
430:       if (this.banderaTodosSeleccionados) {
431:         this.borrarSeleccion()
432:       } else {
433:         plan.seleccionado = false;
434:         const index = this.planesInteres.findIndex(
435:           (x) => x._id == plan._id
436:         );
437:         this.planesInteres.splice(index, 1);
438: 
439:         this.banderaTodosSeleccionados = false;
440:       }
441:     }
442:   }
