113:    */
114:   patch(endpoint: any, element: any) {
115:     return this.http.patch<any>(`${this.path}${endpoint}`, element, this.httpOptions).pipe(
116:       catchError((error) => this.errManager.handleError(error)),
117:     );
118:   }
119: };

